/**
 * Output snapshots for every theme package. They pin what users actually get:
 * - how every Lezer tag resolves (color, font style, weight…) through the real HighlightStyle;
 * - the editor UI CSS generated by EditorView.theme (class names normalized);
 * - the public export surface of each package.
 * A refactor must keep these identical; an intended visual change updates them deliberately (`bun test -u`).
 */
import { describe, expect, test } from 'bun:test';
import { editorCss, loadAllThemes, resolvedHighlights } from './support/themes';

const themes = await loadAllThemes();

describe.each(themes.map((theme) => [theme.id, theme] as const))('%s', (_id, theme) => {
  test('resolved syntax highlighting per tag', () => {
    expect(resolvedHighlights(theme.extension)).toMatchSnapshot();
  });

  test('editor UI CSS', () => {
    expect(editorCss(theme.extension)).toMatchSnapshot();
  });

  test('export surface', () => {
    const surface = Object.keys(theme.module)
      .sort()
      .map((key) => `${key}: ${typeof theme.module[key]}`);
    expect(surface).toMatchSnapshot();
  });
});
